+  border-left: 2px solid var(--accent);
+  padding: 10px 16px;
+  background: var(--surface);
+  margin: 0 0 30px;
+}
+.currency-section {
+  border-top: 1px solid var(--line);
+  padding-top: 26px;
+  margin-top: 32px;
+}
+.currency-section > h2 {
+  color: var(--accent);
+}
+.summary-columns {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
+  gap: 48px;
+}
+.summary-columns h3 {
+  font-size: 16px;
+  font-weight: 600;
+  margin: 14px 0 12px;
+}
+.summary-columns table {
+  width: 100%;
+  table-layout: fixed;
+  border-collapse: collapse;
+  font-size: 14px;
+  line-height: 1.6;
+}
+.summary-columns th,
+.summary-columns td {
+  text-align: left;
+  vertical-align: top;
+  padding: 14px 0;
+  border-bottom: 1px solid var(--line);
+  overflow-wrap: anywhere;
+}
+.summary-columns thead th {
+  font-size: 12px;
+  font-weight: 400;
+  color: var(--muted);
+  padding-top: 0;
+}
+.summary-columns th {
+  font-weight: 500;
+  padding-right: 16px;
+  width: 54%;
+}
+.summary-columns td,
+.summary-columns th:last-child {
+  text-align: right;
+}
+.entry-count,
+.partial-note {
+  display: block;
+  font-size: 11px;
+  font-weight: 400;
+  line-height: 1.7;
+  color: var(--muted);
+  margin-top: 4px;
+}
+.ranking-note {
+  margin: 0 0 12px;
+  color: var(--muted);
+  font-size: 12px;
+  line-height: 1.7;
+}
+.detail-footnote {
+  margin-top: 32px;
+  font-size: 12px;
+}
+.detail-message {
+  padding: 32px 0 80px;
+}
+.detail-message p {
+  color: var(--muted);
+  font-size: 14px;
+  line-height: 1.8;
+}
+.detail-message .loading-indicator {
+  display: block;
+  margin-bottom: 24px;
+}
+.empty-details {
+  padding: 24px 0;
+}
+@media (max-width: 700px) {
+  .summary-columns {
+    grid-template-columns: minmax(0, 1fr);
+    gap: 24px;
+  }
+  .declaration-heading {
+    flex-direction: column;
+    gap: 8px;
+  }
+  .back-link {
+    margin-bottom: 32px;
+  }
+  .funding-list li {
+    padding: 14px 12px;
+    gap: 14px;
+  }
+}
